            ->limit($limit)->offset($start)
            //->leftJoin('p.NomTipodocumento g')
            ->where("p.idsubsistema = ?", $idsubsistema)
            ->execute()->toArray();
        if (count($datos) != 0) {
            $documentos = Array();
            for ($i = 0; $i < count($datos); $i++) {
