                $aux['abreviatura'] = $documento[0]['abreviatura'];
                $documentos[] = $aux;
            }
            return array('cantidad_filas' => count($datos), 'root' => $documentos);
        } else {
            return array('cantidad_filas' => 0, 'root' => Array());
        }
    }

